namespace ghidra.framework.project.tool;

using static org.junit.Assert;

using org.junit;

using generic.test;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.test;
using ghidra.test;

/**
 * The following tests are performed in this test driver for
 * the new front end:
 * (1) Run Project Tool Without Data
 * (2) Run Tool imported from User Space
 */
public class RunToolTest : AbstractGhidraHeadedIntegrationTest {

	private static string DIRECTORY_NAME = AbstractGTest.getTestDirectoryPath();
	private static string TOOL_NAME = "TestTool";

	private Project project;
	private PluginTool runningTool;
	private PluginTool tool;

	/* @Before */
	public void setUp()
    {
		ProjectTestUtils.deleteProject(DIRECTORY_NAME, PROJECT_NAME);
		project = ProjectTestUtils.getProject(DIRECTORY_NAME, PROJECT_NAME);
	}

	/* @After */
	public void tearDown()
    {
		runSwing(new _Anon_Runnable_1());
		ProjectTestUtils.deleteProject(DIRECTORY_NAME, PROJECT_NAME);
	}

	/*
	 * Do the test.
	 * This doTest() routine tests the following requirements:
	 * (1) Run Project Tool Without Data
	 * (2) Run Project Tool With Specified Data
	 * (3) Run Tool imported from User Space
	 * (running a new tool with and without data is done via ChangeToolData)
	 */
	/* @Test */
	public void testRunTool()
    {

		// Make sure old tool instance does not exist since it is not stored within the project
		ProjectTestUtils.deleteTool(project, TOOL_NAME);

		// Create tool and save tool config
		runSwing(new _Anon_Runnable_2());

		try {

			ToolTemplate toolConfig = ProjectTestUtils.saveTool(project, tool);
			runSwing(new _Anon_Runnable_3());

			//
			// TEST 1: launch the tool without data
			//
			ToolManager tm = project.getToolManager();

			// first get the active workspace that will contain the tool
			Workspace[] workspaces = tm.getWorkspaces();

			// the front end will know which one is the active one; just
			// use the first one for the test
			Workspace activeWorkspace = workspaces[0];

			runSwing(new _Anon_Runnable_4());
			assertNotNull(runningTool);
			runSwing(new _Anon_Runnable_5());

		}
		finally {
			// Don't leave the tool in the tool chest
			runSwing(new _Anon_Runnable_6());
		}

	}


	internal class _Anon_Runnable_1 : Runnable
	{

			/* @Override */
			public void run() {
				project.save();
				project.close();
			}
		
	}


	internal class _Anon_Runnable_2 : Runnable
	{

			/* @Override */
			public void run() {
				tool = ProjectTestUtils.getTool(project, null);
				tool.setToolName(TOOL_NAME);
			}
		
	}


	internal class _Anon_Runnable_3 : Runnable
	{

				/* @Override */
				public void run() {
					tool.close();
				}
			
	}


	internal class _Anon_Runnable_4 : Runnable
	{

				/* @Override */
				public void run() {
					runningTool = activeWorkspace.runTool(toolConfig);
				}
			
	}


	internal class _Anon_Runnable_5 : Runnable
	{

				/* @Override */
				public void run() {
					runningTool.close();
				}
			
	}


	internal class _Anon_Runnable_6 : Runnable
	{

				/* @Override */
				public void run() {
					ProjectTestUtils.deleteTool(project, TOOL_NAME);
				}
			
	}

}
